// SPDX-License-Identifier: Apache-2.0
// Self-test of the SPDX header gate: scope, exemptions, generated files, foreign licences, and a --fix that keeps
// shebangs and Dockerfile parser directives first. Fixtures are written into a temporary git repository.
//
//   node --test tools/spdx/

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { after, describe, test } from "node:test";
import {
  checkFile,
  type Exemption,
  globToRegExp,
  hasHeader,
  run,
  styleOf,
  withHeader,
} from "./check-headers.ts";

const H = "SPDX-License-Identifier: Apache-2.0";

describe("scope", () => {
  test("knows the comment style of every source kind and ignores everything else", () => {
    assert.equal(styleOf("a/b.go", ""), "slash");
    assert.equal(styleOf("a/b.tsx", ""), "slash");
    assert.equal(styleOf("a/b.mjs", ""), "slash");
    assert.equal(styleOf("a/b.sql", ""), "dash");
    assert.equal(styleOf("a/b.sh", ""), "hash");
    assert.equal(styleOf("a/Dockerfile", ""), "hash");
    assert.equal(styleOf("a/Dockerfile.runner", ""), "hash");
    assert.equal(styleOf("a/run", "#!/usr/bin/env bash"), "hash");
    assert.equal(styleOf("a/run", "#!/bin/sh"), "hash");
    assert.equal(styleOf("a/run", "#!/usr/bin/env python3"), null);
    assert.equal(styleOf("a/Dockerfile.dockerignore", ""), null);
    for (const p of ["a/b.json", "a/b.md", "a/b.yaml", "a/README", "a/b.css"])
      assert.equal(styleOf(p, ""), null, p);
  });

  test("globs: prefix, * within a segment, ** across segments", () => {
    assert.ok(globToRegExp("db/migrations/").test("db/migrations/0001_x.sql"));
    assert.ok(!globToRegExp("db/migrations/").test("db/gates/g1.sql"));
    assert.ok(globToRegExp("**/testdata/**").test("services/x/testdata/a.go"));
    assert.ok(globToRegExp("**/*.fixture").test("tests/fixtures/api/go-nethttp/go.mod.fixture"));
    assert.ok(!globToRegExp("a/*.go").test("a/b/c.go"));
  });
});

describe("classification", () => {
  const ex: Exemption[] = [{ pattern: "db/migrations/", reason: "checksum-locked" }];

  test("ok, missing, exempt, generated, foreign", () => {
    assert.equal(checkFile("x.go", `// ${H}\npackage x\n`, ex)?.status, "ok");
    assert.equal(checkFile("x.go", "package x\n", ex)?.status, "missing");
    assert.equal(checkFile("db/migrations/0001.sql", "SELECT 1;\n", ex)?.status, "exempt");
    assert.equal(
      checkFile("x.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n", ex)
        ?.status,
      "generated",
    );
    assert.equal(checkFile("src/a.gen.ts", "export {};\n", ex)?.status, "generated");
    const foreign = checkFile("x.js", "// SPDX-License-Identifier: MIT\nexport {};\n", ex);
    assert.equal(foreign?.status, "foreign");
    assert.equal(foreign?.detail, "MIT");
    assert.equal(checkFile("notes.md", "# hi\n", ex), null);
  });

  test("the identifier must be near the top, not anywhere in the file", () => {
    const late = `${"// line\n".repeat(12)}// ${H}\n`;
    assert.equal(hasHeader(late), false);
  });
});

describe("--fix placement", () => {
  test("first line by default", () => {
    assert.equal(withHeader("package x\n", "slash", false), `// ${H}\npackage x\n`);
    assert.equal(withHeader("SELECT 1;\n", "dash", false), `-- ${H}\nSELECT 1;\n`);
  });
  test("after a shebang", () => {
    assert.equal(
      withHeader("#!/usr/bin/env bash\nset -eu\n", "hash", false),
      `#!/usr/bin/env bash\n# ${H}\nset -eu\n`,
    );
  });
  test("after Dockerfile parser directives, which must stay first", () => {
    assert.equal(
      withHeader("# syntax=docker/dockerfile:1.7\n# escape=`\nFROM scratch\n", "hash", true),
      `# syntax=docker/dockerfile:1.7\n# escape=\`\n# ${H}\nFROM scratch\n`,
    );
  });
  test("keeps CRLF line endings", () => {
    assert.equal(withHeader("a;\r\nb;\r\n", "slash", false), `// ${H}\r\na;\r\nb;\r\n`);
  });
});

describe("whole run over a git repository", () => {
  const root = mkdtempSync(join(tmpdir(), "scf-spdx-"));
  after(() => rmSync(root, { recursive: true, force: true }));
  const put = (p: string, text: string) => {
    mkdirSync(dirname(join(root, p)), { recursive: true });
    writeFileSync(join(root, p), text);
  };

  test("reports misses, fixes them in place and then passes", () => {
    execFileSync("git", ["init", "-q"], { cwd: root });
    put(
      "tools/spdx/exemptions.json",
      JSON.stringify({
        exemptions: [{ pattern: "db/migrations/", reason: "checksum-locked migrations" }],
      }),
    );
    put("svc/main.go", "package main\n");
    put("svc/ok.ts", `// ${H}\nexport {};\n`);
    put("svc/Dockerfile", "# syntax=docker/dockerfile:1\nFROM scratch\n");
    put("svc/run", "#!/usr/bin/env bash\necho hi\n");
    put("db/migrations/0001.sql", "SELECT 1;\n");
    put("node_modules/dep/index.js", "module.exports = 1;\n");
    put(".gitignore", "node_modules/\n");

    const before = run(root);
    assert.deepEqual(before.failures.map((f) => f.path).sort(), [
      "svc/Dockerfile",
      "svc/main.go",
      "svc/run",
    ]);
    assert.equal(before.results.find((r) => r.path === "db/migrations/0001.sql")?.status, "exempt");
    assert.equal(
      before.results.some((r) => r.path.startsWith("node_modules/")),
      false,
      "ignored files are out of scope",
    );

    const fixed = run(root, { fix: true });
    assert.equal(fixed.results.filter((r) => r.status === "fixed").length, 3);
    assert.equal(
      readFileSync(join(root, "svc/Dockerfile"), "utf8"),
      `# syntax=docker/dockerfile:1\n# ${H}\nFROM scratch\n`,
    );
    assert.equal(run(root).failures.length, 0);
    assert.equal(readFileSync(join(root, "db/migrations/0001.sql"), "utf8"), "SELECT 1;\n");
  });

  test("an exemption without a reason is refused", () => {
    put("tools/spdx/bad.json", JSON.stringify({ exemptions: [{ pattern: "x/", reason: " " }] }));
    assert.throws(
      () => run(root, { exemptionsFile: join(root, "tools/spdx/bad.json") }),
      /without pattern or reason/,
    );
  });
});
